const $=id=>document.getElementById(id);
let game={time:900,home:0,guest:0,period:1,running:false,enabled:true,pen:{home:[],guest:[]}}, edit=null, digits='', timeout=null, sound=false, drill=-1, last=performance.now(), audio;
const drills=[{title:'Ready for puck drop',text:'Set a 15-minute first period, then start the clock.',task:'SET MAIN CLOCK → 1500 → ENTER → START',event:'start',check:()=>game.period===1&&game.time>899&&game.time<=900},{title:'The whistle blows',text:'The referee blows the whistle. Stop the clock promptly.',task:'Press STOP. Penalty clocks stop with it.',event:'stop',check:()=>!game.running},{title:'Two minutes for tripping',text:'With play stopped, enter a two-minute penalty for HOME #12.',task:'HOME PLAYER PENALTY → 12 → ENTER → 200 → ENTER',event:'penalty',check:()=>game.pen.home.some(p=>p.player===12&&p.remaining===120)},{title:'Back to live play',text:'Start the game clock. The home penalty must count down too.',task:'Enable penalty clocks if needed, then START.',event:'start',check:()=>game.enabled&&game.pen.home.length>0},{title:'Goal, guest!',text:'Stop for the whistle, then add one to the guest score. The referee determines whether a penalty ends.',task:'STOP → GUEST SCORE +1',event:'score',check:()=>!game.running&&game.guest===1},{title:'Clear the released penalty',text:'For this drill the referee confirms #12’s minor ends after the goal.',task:'HOME DELETE PENALTY → 1 → ENTER',event:'delete',check:()=>game.pen.home.length===0},{title:'Protect penalties at the break',text:'Disable penalty clocks before running an intermission clock.',task:'DISABLE PENALTY CLOCKS',event:'penoff',check:()=>!game.enabled}];
function fmt(t){t=Math.max(0,t);if(t<60&&t>0)return t.toFixed(1).padStart(4,'0');let n=Math.ceil(t);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function log(message){const li=document.createElement('li'),t=document.createElement('time');t.textContent=fmt(game.time);li.append(t,document.createTextNode(message));$('log').prepend(li);while($('log').children.length>25)$('log').lastChild.remove()}
function tell(message){$('prompt').textContent=message}
function render(){ $('clock').textContent=timeout===null?fmt(game.time):fmt(timeout);for(const side of ['home','guest']){$(side).textContent=game[side];$(side==='home'?'hp':'gp').textContent=game.pen[side].map(p=>'#'+p.player+'  '+fmt(p.remaining)).join('\n')||'—  —:——'}$('period').textContent=game.period;$('status').textContent=timeout!==null?'● TIME OUT':game.running?'● CLOCK RUNNING':'● CLOCK STOPPED';$('status').style.color=game.running?'#47804b':'#98703a';$('penstate').textContent='PENALTY CLOCKS '+(game.enabled?'ON':'OFF');if(!edit)$('entry').textContent=timeout!==null?'TIME OUT '+fmt(timeout):'MAIN CLOCK '+fmt(game.time);else $('entry').textContent=digits||'_' }
function horn(){document.body.classList.add('honking');setTimeout(()=>document.body.classList.remove('honking'),700);tell('HORN');if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sawtooth';o.frequency.value=180;g.gain.value=.09;o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.65)}catch{tell('Audio unavailable in this browser')}}
function cancel(){edit=null;digits='';tell('HOCKEY · READY');render()}
function begin(type,side){if(game.running||timeout!==null){tell('STOP CLOCK BEFORE EDITING');return}edit={type,side};digits='';tell(type==='time'?'SET MAIN CLOCK · MMSS':type==='delete'?'DELETE PENALTY · SLOT 1 OR 2':'PLAYER NUMBER · 0–99');render()}
function emit(event){if(drill<0)return;const d=drills[drill];if(event===d.event&&d.check()){tell('DRILL COMPLETE');$('task').textContent='✓ Complete. '+(drill===drills.length-1?'You’ve finished the practice shift.':'Continue when you’re ready.');$('next').textContent=drill===drills.length-1?'Practice again ↻':'Next drill →';$('next').disabled=false;log('Drill complete: '+d.title)}}
function enter(){if(!edit||!digits)return;const n=Number(digits);if(edit.type==='player'){if(n>99){tell('PLAYER NUMBER MUST BE 0–99');return}edit.player=n;edit.type='penalty';digits='';tell('PENALTY TIME · MMSS (200 = 2 MIN)');render();return}if(edit.type==='time'||edit.type==='penalty'){let secs=n%100,minutes=Math.floor(n/100);if(secs>59||minutes>99||n===0&&edit.type==='penalty'){tell('INVALID TIME · USE MMSS, SECONDS 00–59');return}if(edit.type==='time'){game.time=minutes*60+secs;log('Main clock set to '+fmt(game.time))}else{game.pen[edit.side].push({player:edit.player,remaining:minutes*60+secs});log(edit.side+' #'+edit.player+' penalty '+fmt(minutes*60+secs));}const event=edit.type==='time'?'set':'penalty';cancel();emit(event);return}if(edit.type==='delete'){if(n<1||n>game.pen[edit.side].length){tell('SELECT AN OCCUPIED SLOT: 1 OR 2');return}const [p]=game.pen[edit.side].splice(n-1,1);log(edit.side+' #'+p.player+' penalty deleted');cancel();emit('delete')}}
function num(n){if(edit&&digits.length<(edit.type==='player'||edit.type==='delete'?2:4)){digits+=n;render()}}
function act(action){const [a,side,delta]=action.split(':');if(a==='set')begin('time');if(a==='pen'){if(game.pen[side].length>=2){tell('TWO SLOTS FULL · RESOLVE BEFORE ADDING');return}begin('player',side)}if(a==='delete')begin('delete',side);if(a==='score'){game[side]=Math.max(0,Math.min(99,game[side]+Number(delta)));log(side+' score '+game[side]);emit('score')}if(a==='period'){if(game.running||timeout!==null){tell('STOP CLOCK BEFORE CHANGING PERIOD');return}game.period=game.period>=9?1:game.period+1;log('Period '+game.period)}if(a==='penon'||a==='penoff'){game.enabled=a==='penon';log('Penalty clocks '+(game.enabled?'enabled':'disabled'));emit(a)}if(a==='horn')horn();if(a==='timeout'){if(edit){tell('FINISH OR CANCEL ENTRY FIRST');return}if(timeout!==null){timeout=null;log('Time out ended')}else{game.running=false;timeout=30;log('30-second time out started')}}render()}
function start(){if(edit){tell('FINISH OR CANCEL ENTRY FIRST');return}if(timeout!==null){tell('END TIME OUT BEFORE STARTING');return}if(game.time<=0){tell('SET MAIN CLOCK FIRST');return}if(!game.running){game.running=true;last=performance.now();log('Clock started');emit('start')}render()}
function stop(){if(game.running){game.running=false;log('Whistle · clock stopped')}emit('stop');render()}
function reset(){game={time:Number($('length').value),home:0,guest:0,period:1,running:false,enabled:true,pen:{home:[],guest:[]}};timeout=null;cancel();$('log').replaceChildren();log('New practice game');last=performance.now()}
function next(){if(drill<0||drill===drills.length-1){reset();drill=0}else drill++;const d=drills[drill];$('tag').textContent='GUIDED DRILL '+(drill+1)+' / '+drills.length;$('drilltitle').textContent=d.title;$('drilltext').textContent=d.text;$('task').textContent=d.task;$('next').textContent='Complete the task to continue';$('next').disabled=true;$('guided').classList.add('selected');$('free').classList.remove('selected')}
for(const n of ['7','8','9','4','5','6','1','2','3','CLEAR','0','ENTER']){const b=document.createElement('button');b.textContent=n;b.onclick=()=>n==='ENTER'?enter():n==='CLEAR'?(digits?(digits='',render()):cancel()):num(n);$('keypad').append(b)}
document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>act(b.dataset.act));$('start').onclick=start;$('stop').onclick=stop;$('next').onclick=next;$('guided').onclick=()=>{if(drill<0)next()};$('free').onclick=()=>{drill=-1;$('free').classList.add('selected');$('guided').classList.remove('selected');$('tag').textContent='FREE PRACTICE';$('drilltitle').textContent='Find your rhythm.';$('drilltext').textContent='Experiment with the console. Your game is yours to run.';$('task').textContent='Set the clock, enter penalties, and practice stopping on the whistle.';$('next').textContent='Start a guided drill ↗';$('next').disabled=false};$('reset').onclick=()=>{if(confirm('Reset clock, scores and penalties?')){reset();if(drill>=0){drill=-1;next()}}};$('length').onchange=()=>tell('PERIOD LENGTH APPLIES ON RESET');$('sound').onclick=()=>{sound=!sound;$('sound').textContent='Sound '+(sound?'on':'off');if(sound)horn()};
document.addEventListener('keydown',e=>{if(['SELECT','INPUT','TEXTAREA','BUTTON'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();game.running?stop():start()}else if(e.key.toLowerCase()==='h')horn();else if(e.key==='Enter')enter();else if(e.key==='Escape')cancel();else if(e.key==='Backspace'){e.preventDefault();digits=digits.slice(0,-1);render()}else if(/^\d$/.test(e.key))num(e.key)});
setInterval(()=>{const now=performance.now(),dt=(now-last)/1000*Number($('speed').value);last=now;if(timeout!==null){timeout=Math.max(0,timeout-dt);if(timeout===0){timeout=null;horn();log('Time out complete')}}else if(game.running){const elapsed=Math.min(dt,game.time);game.time=Math.max(0,game.time-elapsed);if(game.enabled)for(const side of ['home','guest']){for(const p of game.pen[side])p.remaining=Math.max(0,p.remaining-elapsed);game.pen[side]=game.pen[side].filter(p=>{if(p.remaining<=0){log(side+' #'+p.player+' penalty expired');return false}return true})}if(game.time===0){game.running=false;horn();log('Period ended')}}render()},50);log('Practice console ready');render();

document.querySelector('a[href="index.html"]').setAttribute("aria-current","page");
